(1894767, 258607, 17507, '<td valign="top">I wouldn''t exactly call Buddhist scripture and teachings "gospel" - that aside - this is a very pleasing image with a connection to the challenge that I like.</td>', 'I wouldn''t exactly call Buddhist scripture and teachings "gospel" - that aside - this is a very pleasing image with a connection to the challenge that I like.', '2005-11-24 04:32:38.000000', NULL, 1),
(1894769, 259731, 17507, '<td valign="top">great perspective in this shot! good use of lines as well. the rower in his boat when seen together almost look like an airplane.</td>', 'great perspective in this shot! good use of lines as well. the rower in his boat when seen together almost look like an airplane.', '2005-11-24 04:33:46.000000', NULL, 1),
(1894773, 259817, 17507, '<td valign="top">I think this image could be strengthened by the inclusion of more negative space around the boat.</td>', 'I think this image could be strengthened by the inclusion of more negative space around the boat.', '2005-11-24 04:37:19.000000', NULL, 1),
(1894777, 260690, 17507, '<td valign="top">I feel like the title would better reflect the image if you were modifying a 3 to an 8, or something like that, rather than just removing the 3. Technically speaking, your lighting and DOF are well used to deliver your image.</td>', 'I feel like the title would better reflect the image if you were modifying a 3 to an 8, or something like that, rather than just removing the 3. Technically speaking, your lighting and DOF are well used to deliver your image.', '2005-11-24 04:40:04.000000', NULL, 1),
