(1894978, 258713, 44611, '<td valign="top">Brilliantly thought out and captured.  I love the colours and the symmetry.  9 from me.</td>', 'Brilliantly thought out and captured.  I love the colours and the symmetry.  9 from me.', '2005-11-24 09:04:24.000000', NULL, 1),
(1894979, 261147, 44611, '<td valign="top">Superb - I love the clarity; the light; the colour.  Very beautiful image.  9 from me.</td>', 'Superb - I love the clarity; the light; the colour.  Very beautiful image.  9 from me.', '2005-11-24 09:05:05.000000', NULL, 1),
(1894980, 259730, 40344, '<td valign="top">I like the photo but I would like to see it with a tighter crop on the top,</td>', 'I like the photo but I would like to see it with a tighter crop on the top,', '2005-11-24 09:06:15.000000', NULL, 1),
(1894981, 260613, 44611, '<td valign="top">Clever - very clever - and brilliantly executed.  Would I hang it on my wall?  No, so it doesn''t quite get up to the 9/10 level but a definite 8.  Well done with this shot.</td>', 'Clever - very clever - and brilliantly executed.  Would I hang it on my wall?  No, so it doesn''t quite get up to the 9/10 level but a definite 8.  Well done with this shot.', '2005-11-24 09:06:15.000000', NULL, 1),
(1894982, 260545, 44611, '<td valign="top">Very well seen and captured.  Perfect for this challenger - and I''m a sucker for zebras - they are so photogenic.  An 8 - well done.</td>', 'Very well seen and captured.  Perfect for this challenger - and I''m a sucker for zebras - they are so photogenic.  An 8 - well done.', '2005-11-24 09:06:57.000000', NULL, 1),
(1894983, 260545, 24940, '<td valign="top">Tighter cropping, straightening, desaturation and a thinner border would have made this a fantastic photograph, as opposed to a decent one.  GREAT concept, though!  :)</td>', 'Tighter cropping, straightening, desaturation and a thinner border would have made this a fantastic photograph, as opposed to a decent one.  GREAT concept, though!  :)', '2005-11-24 09:07:08.000000', NULL, 1),
(1894985, 261158, 24940, '<td valign="top">Very "clevel"  :))  :))</td>', 'Very "clevel"  :))  :))', '2005-11-24 09:08:01.000000', NULL, 1),
(1894987, 261063, 44611, '<td valign="top">I feel this needed some more space, or something  else to improve the composition - perhaps the crop was too tight.  Exceptionally good detail on the limes though.</td>', 'I feel this needed some more space, or something  else to improve the composition - perhaps the crop was too tight.  Exceptionally good detail on the limes though.', '2005-11-24 09:09:37.000000', NULL, 1),
(1894989, 260244, 40344, '<td valign="top">Excellent! I feel the mood.</td>', 'Excellent! I feel the mood.', '2005-11-24 09:10:15.000000', NULL, 1),
(1894991, 259729, 44611, '<td valign="top">Good light and those frosty outlines are very distinct.</td>', 'Good light and those frosty outlines are very distinct.', '2005-11-24 09:11:01.000000', NULL, 1),
(1894992, 261157, 24940, '<td valign="top">Got spellcheck?</td>', 'Got spellcheck?', '2005-11-24 09:12:10.000000', NULL, 1),
(1894993, 260614, 40344, '<td valign="top">original idea nicely done</td>', 'original idea nicely done', '2005-11-24 09:12:23.000000', NULL, 1),
(1894995, 258589, 24940, '<td valign="top">Needs to be straighter and the smudges should not be on the chrome.</td>', 'Needs to be straighter and the smudges should not be on the chrome.', '2005-11-24 09:14:05.000000', NULL, 1),
(1894996, 261004, 44611, '<td valign="top">Looks possibly as though a bit too much saturation was used.  Also might have benefited from a slightly tighter crop.</td>', 'Looks possibly as though a bit too much saturation was used.  Also might have benefited from a slightly tighter crop.', '2005-11-24 09:14:27.000000', NULL, 1),
(1894998, 259980, 44611, '<td valign="top">Cute, cute snapshot - great detail.  My, they look like angels with dirty faces!</td>', 'Cute, cute snapshot - great detail.  My, they look like angels with dirty faces!', '2005-11-24 09:15:29.000000', NULL, 1),
(1895000, 259741, 24940, '<td valign="top">Quite a yawn but more of a "stretch"!  :))</td>', 'Quite a yawn but more of a "stretch"!  :))', '2005-11-24 09:15:58.000000', NULL, 1),
(1895001, 260263, 44611, '<td valign="top">Nice red flower, could do with some additional contrast to bring it out a bit more - and the connection with even is really stretching it!</td>', 'Nice red flower, could do with some additional contrast to bring it out a bit more - and the connection with even is really stretching it!', '2005-11-24 09:16:31.000000', NULL, 1),
(1895002, 261010, 40344, '<td valign="top">lovely baby shot especially the blue eyes in a BW</td>', 'lovely baby shot especially the blue eyes in a BW', '2005-11-24 09:16:35.000000', NULL, 1),
(1895004, 259945, 44611, '<td valign="top">Fabulous sky and a good angle - this would in fact have been a brilliant image - without the trees!  I think they are rather superflous - and the power/telegraph lines are very distracting.  If you''d just tilted your camera back a bit more and missed them you could have got a much higher score.</td>', 'Fabulous sky and a good angle - this would in fact have been a brilliant image - without the trees!  I think they are rather superflous - and the power/telegraph lines are very distracting.  If you''d just tilted your camera back a bit more and missed them you could have got a much higher score.', '2005-11-24 09:18:54.000000', NULL, 1),
(1895007, 258775, 24940, '<td valign="top">Spotty background kills potentially GREAT image.  I realize only basic editing allowed but attention before shooting could have worked.  I REALLY like this, otherwise!  :)</td>', 'Spotty background kills potentially GREAT image.  I realize only basic editing allowed but attention before shooting could have worked.  I REALLY like this, otherwise!  :)', '2005-11-24 09:19:48.000000', NULL, 1),
(1895009, 259891, 40344, '<td valign="top">I usually don''t like photos of rundown urban buildings but there is something compelling about this one that you have captured, ... the lighting, the colour the composition. Congrats</td>', 'I usually don''t like photos of rundown urban buildings but there is something compelling about this one that you have captured, ... the lighting, the colour the composition. Congrats', '2005-11-24 09:20:28.000000', NULL, 1),
(1895010, 260639, 24940, '<td valign="top">Bad focus.</td>', 'Bad focus.', '2005-11-24 09:21:02.000000', NULL, 1),
(1895012, 259835, 44611, '<td valign="top">A good idea, but you''re let down in your execution and composition.  The pencils are too central in the image and you needed to crop this tighter I think.  Actually I think it would have looked better rotated rightward 90 degrees.  Nonetheless, the focus was fair and and the clarity of the pencils is pretty good.</td>', 'A good idea, but you''re let down in your execution and composition.  The pencils are too central in the image and you needed to crop this tighter I think.  Actually I think it would have looked better rotated rightward 90 degrees.  Nonetheless, the focus was fair and and the clarity of the pencils is pretty good.', '2005-11-24 09:21:48.000000', NULL, 1),
(1895014, 261070, 44611, '<td valign="top">A good attempt but a shame that the second seed pod is not all in the frame - it rather loses the point.  You''ve tried well to bring out the dof with the focus on the LHS pod but it hasn''t quite worked out sharply enough and blends into the background a bit too much.</td>', 'A good attempt but a shame that the second seed pod is not all in the frame - it rather loses the point.  You''ve tried well to bring out the dof with the focus on the LHS pod but it hasn''t quite worked out sharply enough and blends into the background a bit too much.', '2005-11-24 09:23:18.000000', NULL, 1),
(1895015, 260711, 44611, '<td valign="top">Great concept but I don''t like the execution I''m afraid.  The finish of this is just too confusing for me - too fuzzy.</td>', 'Great concept but I don''t like the execution I''m afraid.  The finish of this is just too confusing for me - too fuzzy.', '2005-11-24 09:24:58.000000', NULL, 1),
(1895017, 259994, 44611, '<td valign="top">I want to this to work with that lovely Old Master paint feel - but sadly, it just does not.  It may be that patch of light to top right that keeps drawing my eye and spoiling the finish.  A real shame because I think this could have been stunning.</td>', 'I want to this to work with that lovely Old Master paint feel - but sadly, it just does not.  It may be that patch of light to top right that keeps drawing my eye and spoiling the finish.  A real shame because I think this could have been stunning.', '2005-11-24 09:27:33.000000', NULL, 1),
(1895019, 260652, 44611, '<td valign="top">Well seen.  This could have done with slightly sharper focus I think.</td>', 'Well seen.  This could have done with slightly sharper focus I think.', '2005-11-24 09:28:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1895020, 259734, 44611, '<td valign="top">Cute snap.  Good that the swans are looking at you - they are horrors for turning away.</td>', 'Cute snap.  Good that the swans are looking at you - they are horrors for turning away.', '2005-11-24 09:29:29.000000', NULL, 1),
(1895021, 258324, 44611, '<td valign="top">Two pigeons, 1 boat, 1 very famous mosque.   Sadly I think you had a rather foggy day on the Bosphorus which didn''t help this image at all.</td>', 'Two pigeons, 1 boat, 1 very famous mosque.   Sadly I think you had a rather foggy day on the Bosphorus which didn''t help this image at all.', '2005-11-24 09:31:55.000000', NULL, 1),
(1895033, 260265, 44611, '<td valign="top">This is potentially brilliant, but doesn''t seem to have quite enough contrast on my monitor to truly pull it off - the colours are just too subtle.  But then - and I''m rambling here just looking at it - those subtle colours do work and it''s growing on me a lot.  I''ve definitely revised my score upward since my first viewing.</td>', 'This is potentially brilliant, but doesn''t seem to have quite enough contrast on my monitor to truly pull it off - the colours are just too subtle.  But then - and I''m rambling here just looking at it - those subtle colours do work and it''s growing on me a lot.  I''ve definitely revised my score upward since my first viewing.', '2005-11-24 09:43:55.000000', NULL, 1),
(1895036, 258507, 44611, '<td valign="top">The contrast and angle really make this shot.  Well done.</td>', 'The contrast and angle really make this shot.  Well done.', '2005-11-24 09:47:16.000000', NULL, 1),
(1895039, 260159, 44611, '<td valign="top">Very nicely done - works so well in b &amp; w.</td>', 'Very nicely done - works so well in b & w.', '2005-11-24 09:47:57.000000', NULL, 1),
(1895073, 258531, 23962, '<td valign="top">beautifull.</td>', 'beautifull.', '2005-11-24 10:20:59.000000', NULL, 1),
