(1896501, 260441, 27763, '<td valign="top">Clever idea.  Well executed.  Good luck!</td>', 'Clever idea.  Well executed.  Good luck!', '2005-11-25 08:54:59.000000', NULL, 1),
(1896504, 260159, 27763, '<td valign="top">Nicely done.  I like the curves and the tones.  Good title, too.</td>', 'Nicely done.  I like the curves and the tones.  Good title, too.', '2005-11-25 08:59:30.000000', NULL, 1),
(1896506, 258877, 27763, '<td valign="top">Not sure what I''m looking at, but it''s kinda cool!  Good luck.</td>', 'Not sure what I''m looking at, but it''s kinda cool!  Good luck.', '2005-11-25 09:01:21.000000', NULL, 1),
(1896508, 260864, 27763, '<td valign="top">Nice. Looks like an impressionistic painting.</td>', 'Nice. Looks like an impressionistic painting.', '2005-11-25 09:02:10.000000', NULL, 1),
(1896512, 258738, 27763, '<td valign="top">I really like the composition and lighting.  The edge in the upper right corner adds interest. Good luck.</td>', 'I really like the composition and lighting.  The edge in the upper right corner adds interest. Good luck.', '2005-11-25 09:06:28.000000', NULL, 1),
(1896513, 260414, 27763, '<td valign="top">Holy sharpness, batman!  This has incredible sharpness and amazingly vibrant colors, without looking overprocessed.  Very nice photo.  Good luck.</td>', 'Holy sharpness, batman!  This has incredible sharpness and amazingly vibrant colors, without looking overprocessed.  Very nice photo.  Good luck.', '2005-11-25 09:08:01.000000', NULL, 1),
(1896515, 259888, 27763, '<td valign="top">Very nice!  I like how the water is so clear and the leaves appear to float above it.   In the future, you might want to size your photos such that the longest dimension is 640 pixels.  Voters tend to be turned off by smaller pictures.  Good luck.</td>', 'Very nice!  I like how the water is so clear and the leaves appear to float above it.   In the future, you might want to size your photos such that the longest dimension is 640 pixels.  Voters tend to be turned off by smaller pictures.  Good luck.', '2005-11-25 09:12:36.000000', NULL, 1),
(1896516, 260396, 45857, '<td valign="top">Sorry, missed that day in math. I would have like to see all of the fourth ear plug, other than that its a nice composition.</td>', 'Sorry, missed that day in math. I would have like to see all of the fourth ear plug, other than that its a nice composition.', '2005-11-25 09:13:06.000000', NULL, 1),
(1896518, 260472, 27763, '<td valign="top">Gotta love cool stairwells!  Good luck.</td>', 'Gotta love cool stairwells!  Good luck.', '2005-11-25 09:14:02.000000', NULL, 1),
(1896520, 258718, 45857, '<td valign="top">This one stretches the enevolpe of the topic, just a bit forced. I do like the study of the mundane</td>', 'This one stretches the enevolpe of the topic, just a bit forced. I do like the study of the mundane', '2005-11-25 09:14:44.000000', NULL, 1),
(1896524, 260938, 27763, '<td valign="top">At first glance, I thought "Oh, just a picture of someone''s butt."  But this is actually really good. It''s a wonderful abstract composition with nice lighting.   In the future, you might want to size your photo such that the longest dimension is 640 pixels.  Yours is only 259 pixels.  Voters are turned off by smaller pictures.</td>', 'At first glance, I thought "Oh, just a picture of someone''s butt."  But this is actually really good. It''s a wonderful abstract composition with nice lighting.   In the future, you might want to size your photo such that the longest dimension is 640 pixels.  Yours is only 259 pixels.  Voters are turned off by smaller pictures.', '2005-11-25 09:17:08.000000', NULL, 1),
(1896525, 260244, 45857, '<td valign="top">Very moody image. i would have cropped out the window on the right, would like to see it ''darker'' and it would be interesting to see this one in B&amp;W. Great subject for "noir'' approach.</td>', 'Very moody image. i would have cropped out the window on the right, would like to see it ''darker'' and it would be interesting to see this one in B&W. Great subject for "noir'' approach.', '2005-11-25 09:18:20.000000', NULL, 1),
(1896526, 260244, 27763, '<td valign="top">Cool.  Love the fogginess in the air.  The two figures add a nice point of interest.  I wish they were darker, but there''s nothing you can do about that in a "Basic Editing" challenge!  Good luck.</td>', 'Cool.  Love the fogginess in the air.  The two figures add a nice point of interest.  I wish they were darker, but there''s nothing you can do about that in a "Basic Editing" challenge!  Good luck.', '2005-11-25 09:18:49.000000', NULL, 1),
(1896528, 259730, 27763, '<td valign="top">Lovely color palette in this photo.  Browns, greens, and yellows.  Great sharpness, lighting, and nice composition, too.  Good luck.</td>', 'Lovely color palette in this photo.  Browns, greens, and yellows.  Great sharpness, lighting, and nice composition, too.  Good luck.', '2005-11-25 09:20:20.000000', NULL, 1),
(1896532, 259817, 45857, '<td valign="top">Certainly an obscure approcah to the topic. The close vertical frame works well, though the boat is a bit off center.</td>', 'Certainly an obscure approcah to the topic. The close vertical frame works well, though the boat is a bit off center.', '2005-11-25 09:23:46.000000', NULL, 1);
