(1896537, 260863, 27763, '<td valign="top">Good one.  The placement of the horizon on the center of the photo definitely creates a sense of balance and "evenness".</td>', 'Good one.  The placement of the horizon on the center of the photo definitely creates a sense of balance and "evenness".', '2005-11-25 09:25:41.000000', NULL, 1),
(1896543, 260690, 27763, '<td valign="top">Nicely done.  A good idea that''s well executed.</td>', 'Nicely done.  A good idea that''s well executed.', '2005-11-25 09:30:20.000000', NULL, 1),
