(1896548, 260857, 45857, '<td valign="top">Even lighting is a hard concept to extract when faced with one pillar as your subject</td>', 'Even lighting is a hard concept to extract when faced with one pillar as your subject', '2005-11-25 09:34:28.000000', NULL, 1),
