(1897041, 259885, 43190, '<td valign="top">I wish it were horizontal...</td>', 'I wish it were horizontal...', '2005-11-25 16:16:31.000000', NULL, 1),
(1897042, 260509, 43148, '<td valign="top">nicely done (I am not lion about that), only thing I did not like was the tall fence as backdrop, course NOTHING you could do about that - except maybe blur it out a bit</td>', 'nicely done (I am not lion about that), only thing I did not like was the tall fence as backdrop, course NOTHING you could do about that - except maybe blur it out a bit', '2005-11-25 16:16:47.000000', NULL, 1),
