(1897052, 260270, 43148, '<td valign="top">as with the other pair of lions, wish I could not see the walls behind them, but well done photo</td>', 'as with the other pair of lions, wish I could not see the walls behind them, but well done photo', '2005-11-25 16:21:08.000000', NULL, 1),
(1897053, 260727, 45857, '<td valign="top">Equality is only a dream, unfortunately</td>', 'Equality is only a dream, unfortunately', '2005-11-25 16:21:49.000000', NULL, 1),
(1897057, 260555, 43148, '<td valign="top">photo is  bit "dicey" but nicely done overall, simple and maybe not exciting enough to score high</td>', 'photo is  bit "dicey" but nicely done overall, simple and maybe not exciting enough to score high', '2005-11-25 16:22:59.000000', NULL, 1),
(1897058, 259988, 45857, '<td valign="top">Good capture, a mating pair.</td>', 'Good capture, a mating pair.', '2005-11-25 16:23:21.000000', NULL, 1),
