(1897182, 260414, 43148, '<td valign="top">nicely captured image of beautiful ducks, one on left looks almost as if he had been shot, highly illegal if true, but great color, nice dof, one of my favorites for sure</td>', 'nicely captured image of beautiful ducks, one on left looks almost as if he had been shot, highly illegal if true, but great color, nice dof, one of my favorites for sure', '2005-11-25 17:50:40.000000', NULL, 1),
(1897187, 261002, 43148, '<td valign="top">nice cute capture, made me smile</td>', 'nice cute capture, made me smile', '2005-11-25 17:52:21.000000', NULL, 1),
