(1897231, 259945, 45857, '<td valign="top">I like the tall framing.</td>', 'I like the tall framing.', '2005-11-25 18:15:09.000000', NULL, 1),
(1897233, 259410, 44490, '<td valign="top">Great illusion - had me guessing.  Great idea, and nicely executed arrangement, framing, focus, and DOF.</td>', 'Great illusion - had me guessing.  Great idea, and nicely executed arrangement, framing, focus, and DOF.', '2005-11-25 18:15:22.000000', NULL, 1),
