(1897239, 260701, 45857, '<td valign="top">Unique insect.</td>', 'Unique insect.', '2005-11-25 18:17:32.000000', NULL, 1),
(1897240, 260787, 44490, '<td valign="top">Good title, arrangement, and color.  I little more foreground focus or more DOF would help.</td>', 'Good title, arrangement, and color.  I little more foreground focus or more DOF would help.', '2005-11-25 18:17:48.000000', NULL, 1),
(1897242, 260509, 45857, '<td valign="top">Nice family portrait.</td>', 'Nice family portrait.', '2005-11-25 18:18:04.000000', NULL, 1),
(1897245, 259604, 44490, '<td valign="top">Nice panning capture, sharp, and captures motion.  Framing so subject is left of exact center might help.</td>', 'Nice panning capture, sharp, and captures motion.  Framing so subject is left of exact center might help.', '2005-11-25 18:20:00.000000', NULL, 1),
