(1897251, 259994, 44490, '<td valign="top">Nice color, but too blurry - better focus and DOF would help a lot.</td>', 'Nice color, but too blurry - better focus and DOF would help a lot.', '2005-11-25 18:22:47.000000', NULL, 1),
(1897255, 260639, 44490, '<td valign="top">Cute figurine.  More DOF would help so that the hands are in focus as well.</td>', 'Cute figurine.  More DOF would help so that the hands are in focus as well.', '2005-11-25 18:24:20.000000', NULL, 1),
(1897257, 260583, 44490, '<td valign="top">Nice color and interesting angle kept me looking.  Just a little more DOF would help.</td>', 'Nice color and interesting angle kept me looking.  Just a little more DOF would help.', '2005-11-25 18:27:13.000000', NULL, 1),
(1897260, 258589, 44490, '<td valign="top">Nice DOF and bokeh.  Cleaning the fixture might have removed the distracting foreground blurs where we probably want more sharpness.</td>', 'Nice DOF and bokeh.  Cleaning the fixture might have removed the distracting foreground blurs where we probably want more sharpness.', '2005-11-25 18:29:46.000000', NULL, 1),
(1897261, 261119, 43031, '<td valign="top">this picture would have done better I think if the very front of the bottom die were in focus also.</td>', 'this picture would have done better I think if the very front of the bottom die were in focus also.', '2005-11-25 18:30:23.000000', NULL, 1),
(1897265, 258593, 44490, '<td valign="top">Nice idea and B&amp;W choice.  You probably got the texture that you wanted, but I would hope for as much sharpness as possible while maintaining the marble-like appearance.</td>', 'Nice idea and B&W choice.  You probably got the texture that you wanted, but I would hope for as much sharpness as possible while maintaining the marble-like appearance.', '2005-11-25 18:32:17.000000', NULL, 1),
(1897275, 260109, 45857, '<td valign="top">Good macro, interesting colors.</td>', 'Good macro, interesting colors.', '2005-11-25 18:38:18.000000', NULL, 1),
(1897280, 260333, 44490, '<td valign="top">Composition, angles, mirror tiles, and those eyes make this exceptional, and definitely not just another pet shot.  Only thing that I don''t like is the bar on the floor, which is pretty picky.  Love it!</td>', 'Composition, angles, mirror tiles, and those eyes make this exceptional, and definitely not just another pet shot.  Only thing that I don''t like is the bar on the floor, which is pretty picky.  Love it!', '2005-11-25 18:39:53.000000', NULL, 1),
(1897281, 258854, 45857, '<td valign="top">Beautiful mystical shot, perhaps a few dirt spots.</td>', 'Beautiful mystical shot, perhaps a few dirt spots.', '2005-11-25 18:40:21.000000', NULL, 1),
(1897288, 260586, 44490, '<td valign="top">Nice and sharp action capture - wish you had been able to catch an expression with it.  There appears to be a strange blue blur on the shoe, do you know what caused it?</td>', 'Nice and sharp action capture - wish you had been able to catch an expression with it.  There appears to be a strange blue blur on the shoe, do you know what caused it?', '2005-11-25 18:43:49.000000', NULL, 1),
(1897289, 259801, 45857, '<td valign="top">Good human interest shot</td>', 'Good human interest shot', '2005-11-25 18:45:05.000000', NULL, 1),
(1897291, 258531, 44490, '<td valign="top">I like the hands and deck in the background.  Nice focus, DOF, and composition.</td>', 'I like the hands and deck in the background.  Nice focus, DOF, and composition.', '2005-11-25 18:45:52.000000', NULL, 1),
(1897295, 260512, 44490, '<td valign="top">More sharpness, saturation, and contrast would help.</td>', 'More sharpness, saturation, and contrast would help.', '2005-11-25 18:48:31.000000', NULL, 1),
(1897299, 258775, 44490, '<td valign="top">Great lighting gives nice contrast, better focus or sharpness would help.</td>', 'Great lighting gives nice contrast, better focus or sharpness would help.', '2005-11-25 18:49:59.000000', NULL, 1),
(1897320, 259945, 2866, '<td valign="top">Good shot except the wires are really distracting.</td>', 'Good shot except the wires are really distracting.', '2005-11-25 19:01:31.000000', NULL, 1),
(1897322, 258324, 2866, '<td valign="top">Without the title, I wouldn''t get it.</td>', 'Without the title, I wouldn''t get it.', '2005-11-25 19:03:01.000000', NULL, 1),
(1897323, 258854, 2866, '<td valign="top">Very nice.</td>', 'Very nice.', '2005-11-25 19:03:36.000000', NULL, 1),
(1897327, 258879, 2866, '<td valign="top">Great shot!</td>', 'Great shot!', '2005-11-25 19:05:33.000000', NULL, 1),
(1897334, 258531, 2866, '<td valign="top">Nice shot. Too bad about the noise on the hands.</td>', 'Nice shot. Too bad about the noise on the hands.', '2005-11-25 19:08:24.000000', NULL, 1),
(1897396, 261017, 44490, '<td valign="top">Nice color and skyline, but rails are too dark, almost not visible.  PS brightness +9, contrast +47 seems to almost work for simple processing.</td>', 'Nice color and skyline, but rails are too dark, almost not visible.  PS brightness +9, contrast +47 seems to almost work for simple processing.', '2005-11-25 19:40:41.000000', NULL, 1),
(1897405, 261158, 44490, '<td valign="top">Nice idea, and excellent execution, focus, composition, and DOF.  Maybe tighten by moving the foreground/hand closer to the background tiles?</td>', 'Nice idea, and excellent execution, focus, composition, and DOF.  Maybe tighten by moving the foreground/hand closer to the background tiles?', '2005-11-25 19:47:01.000000', NULL, 1),
(1897411, 260701, 44490, '<td valign="top">Difficult capture - more leg and antennae would be better.  How about bumping up brightness, contrast, and saturation to compensate for underexposure and muted underside colors?</td>', 'Difficult capture - more leg and antennae would be better.  How about bumping up brightness, contrast, and saturation to compensate for underexposure and muted underside colors?', '2005-11-25 19:49:52.000000', NULL, 1),
(1897417, 260168, 44490, '<td valign="top">Pose and fence framing outside DOF is interesting, but white bar on left is annoying, less bar and not-white, e.g., brown, would be much better.</td>', 'Pose and fence framing outside DOF is interesting, but white bar on left is annoying, less bar and not-white, e.g., brown, would be much better.', '2005-11-25 19:57:14.000000', NULL, 1),
(1897419, 260414, 44490, '<td valign="top">Beautiful colors, and nice action capture.</td>', 'Beautiful colors, and nice action capture.', '2005-11-25 19:58:16.000000', NULL, 1),
(1897421, 260244, 44490, '<td valign="top">Nice composition, but would like something in the image to be sharper, like the couple.</td>', 'Nice composition, but would like something in the image to be sharper, like the couple.', '2005-11-25 19:59:29.000000', NULL, 1),
(1897426, 260613, 44490, '<td valign="top">Great balancing act, composition, and colors, and another head scratcher, especially with the liquid...  Love it!</td>', 'Great balancing act, composition, and colors, and another head scratcher, especially with the liquid...  Love it!', '2005-11-25 20:02:12.000000', NULL, 1),
(1897428, 260857, 44490, '<td valign="top">Symmetry is even, but probably not as interesting as some asymmetry.  More sharpness would help.</td>', 'Symmetry is even, but probably not as interesting as some asymmetry.  More sharpness would help.', '2005-11-25 20:03:48.000000', NULL, 1),
(1897443, 259790, 44490, '<td valign="top">Nice idea.  More sharpness would help, and maybe another element, like a finger.</td>', 'Nice idea.  More sharpness would help, and maybe another element, like a finger.', '2005-11-25 20:10:01.000000', NULL, 1),
(1897445, 260673, 44490, '<td valign="top">Beautiful image, looking forward to your notes on how you did it.</td>', 'Beautiful image, looking forward to your notes on how you did it.', '2005-11-25 20:11:23.000000', NULL, 1),
(1897451, 260371, 41802, '<td valign="top">Nice action shot!</td>', 'Nice action shot!', '2005-11-25 20:21:56.000000', NULL, 1),
